"""Export Gymnax's default tasks, fixed maps, action sets and render palettes."""

import gymnax
import numpy as np
import seaborn as sns

from envpool.gymnax.oracle import make_oracle


def bound(value: float) -> str:
    """Encode a scalar bound as a C++ literal."""
    if abs(value) == np.finfo(np.float32).max:
        return "-kMax" if value < 0 else "kMax"
    return str(int(value)) if value.is_integer() else f"{value:g}f"


def main() -> None:
    """Print the native registration and task data."""
    shared, entries, kinds = [], [], []
    palettes: set[int] = set()
    print("// Generated by //third_party/gymnax:generate_registry.")
    for task in gymnax.registered_envs:
        env, params = make_oracle(task)
        name, family = task.split("-")
        limit = int(params.max_steps_in_episode)
        if family.startswith("v") or name in ("Catch", "FrozenLake"):
            module = "classic_control" if family.startswith("v") else "toy_text"
            shared.append(f'  {{"{task}", "{module}", "{name}", {limit}}},')
            continue

        obs, act = env.observation_space(params), env.action_space(params)
        shape = ", ".join(map(str, obs.shape))
        low, high = (
            bound(float(np.min(obs.low))),
            bound(float(np.max(obs.high))),
        )
        continuous = not hasattr(act, "n")
        force = bound(float(np.max(act.high))) if continuous else "0"
        group = "Robot" if continuous else "Discrete"
        if name in ("Snake", "FourRooms"):
            group = name
        minimal = ", ".join(map(str, getattr(env, "minimal_action_set", ())))
        colors = "nullptr"
        if family == "MinAtar" or name == "Pong":
            channels = obs.shape[-1]
            palettes.add(channels)
            colors = f"kColors{channels}"
        kinds.append(name)
        entries.append(
            f'  {{"{task}", "{group}", Kind::{name}, {limit}, '
            f"{{{shape}}}, {env.num_actions}, {low}, {high}, {force}, "
            f"{{{minimal}}}, {colors}}},"
        )
        if name in ("DeepSea", "MetaMaze", "FourRooms"):
            if name == "DeepSea":
                cells = np.asarray(env.action_mapping).astype(str)
            else:
                cells = np.where(env.occupied_map, "#", ".")
            print(f"inline constexpr char k{name}[] =")
            rows = ('    "' + "".join(row) + '"' for row in cells)
            print("\n".join(rows) + ";")

    for n in sorted(palettes):
        rgb = (255 * np.asarray(sns.color_palette("cubehelix", n))).astype(int)
        colors = ", ".join(f"{{{r}, {g}, {b}}}" for r, g, b in rgb)
        print(
            f"inline constexpr Color kColors{n}[] = {{{{0, 0, 0}}, {colors}}};"
        )
    print("enum class Kind { " + ", ".join(kinds) + " };")
    print("inline constexpr SharedTask kShared[] = {", *shared, "};", sep="\n")
    print("inline const Task kTasks[] = {", *entries, "};", sep="\n")


if __name__ == "__main__":
    main()
